CREATE TABLE wompi_accounts (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, environment VARCHAR(4) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, public_key VARCHAR(120) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, private_key_ciphertext TEXT NOT NULL, events_secret_ciphertext TEXT NOT NULL, integrity_secret_ciphertext TEXT NOT NULL, events_token_hash CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, events_token_ciphertext TEXT NOT NULL, merchant_name VARCHAR(200) NULL, payment_methods TEXT NULL, status VARCHAR(10) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'pending', last_error VARCHAR(500) NULL, last_tested_at DATETIME(6) NULL, last_event_at DATETIME(6) NULL, last_rejected_at DATETIME(6) NULL, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY (id), UNIQUE KEY wompi_accounts_user (user_id), UNIQUE KEY wompi_accounts_events_token (events_token_hash), CONSTRAINT wompi_accounts_user_fk FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, CONSTRAINT wompi_accounts_env_ck CHECK (environment IN ('test','prod')), CONSTRAINT wompi_accounts_status_ck CHECK (status IN ('pending','connected','error'))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
